<?php declare(strict_types=1);use PHPUnit\Framework\TestCase;final class ToolResultMailerTest extends TestCase {public function testUsesServerResultAndDropsUnallowedInput():void{$mail=(new ToolResultMailer())->render('markup-margin',['mode'=>'markup','percent'=>30,'cost'=>400,'result'=>999,'evil'=>'<script>alert(1)</script>']);$this->assertStringContainsString('$520.00',$mail['plain']);$this->assertStringNotContainsString('999',$mail['plain']);$this->assertStringNotContainsString('<script>',$mail['html']);$this->assertArrayNotHasKey('evil',$mail['data']['inputs']);}}
